// The bundled food table (TECH-SPEC section 9). `foods.json` is generated by `pnpm foods:build` from USDA SR Legacy and
// FNDDS, SG FoodID, the Thai FCD (INMU) and `data/food-list.csv`; nobody types a nutrient value. It loads lazily and works
// offline.
import type { FoodMemory, MealItem } from '../../../shared/records';
import { compact, fold, norm } from '../../../shared/text';
import { prefs } from '$lib/prefs.svelte';

export type FoodTag = 'dense' | 'protein' | 'drink' | 'oil' | 'staple' | 'thai';
export type FoodSet = 'usda-sr-legacy' | 'usda-fndds' | 'sg-foodid' | 'thai-fcd' | 'thai-fcd-owner' | 'recipe';
export type Food = {
  id: string;
  name: string;
  aliases: string[];
  per100: { kcal: number; protein: number; carbs: number; fat: number; fiber?: number };
  /** the first is the default */
  portions: Array<{ label: string; grams: number }>;
  tags: FoodTag[];
  /** the table and the food's id in it: an FDC id for USDA, a crId for SG FoodID, `owner:` or `inmu:` and the code for
   * the Thai FCD (N3), `recipe:` and the recipe's id for a dish worked out from its ingredients (R2); a Thai page's URL
   * or the first page of the recipe, and which value was worked out by Atwater when the table lacked it */
  source: { set: FoodSet; id: string; url?: string; derived?: 'kcal' | 'carbs' };
};

let table: Promise<Food[]> | null = null;
/** The table, loaded once. A failed load (offline before it was cached) retries on the next call. */
export function loadFoods(): Promise<Food[]> {
  table ??= import('./foods.json').then((m) => m.default as Food[]).catch((e) => { table = null; throw e; });
  return table;
}

export { norm };

/** 4 the whole name, 3 prefix, 2 word start, 1 substring, 0 no match: of the query against one name or alias. */
const part = (s: string, q: string) => (s === q ? 4 : s.startsWith(q) ? 3 : s.includes(` ${q}`) ? 2 : s.includes(q) ? 1 : 0);

type Keys = { raw: string; fold: string; words: string[]; compact: string };
const keysOf = new WeakMap<Food, Keys[]>();
/** A food's name and aliases in the three forms a query is read in, made once (983 rows by a few names). */
function keys(f: Food): Keys[] {
  let k = keysOf.get(f);
  if (!k) keysOf.set(f, (k = [f.name, ...f.aliases].map((t) => { const fo = fold(t); return { raw: norm(t), fold: fo, words: fo.split(' '), compact: compact(t) }; })));
  return k;
}

/** The best of one food's names against the query, 0 to 12. Exact reading scores 3 per tier, the folded reading of
 * Thai romanisation variants (khao and kao, phad and pad) one less, the same with the spaces dropped ("krapao") two
 * less, and a multi word query whose every word starts some word of the name, in any order, sits between word start and
 * substring. So a spelling variant never beats an exact match of the same kind. */
function score(f: Food, q: { raw: string; fold: string; words: string[]; compact: string }) {
  let best = 0;
  for (const k of keys(f)) {
    const a = part(k.raw, q.raw) * 3;
    const b = part(k.fold, q.fold) * 3 - 1;
    const c = q.compact.length >= 4 ? (k.compact === q.compact ? 4 : k.compact.startsWith(q.compact) ? 3 : k.compact.includes(q.compact) ? 1 : 0) * 3 - 2 : 0;
    const d = q.words.length > 1 && q.words.every((w) => k.words.some((x) => x.startsWith(w))) ? 4 : 0;
    best = Math.max(best, a, b, c, d);
  }
  return best;
}

/** The phone reads Thai (a Thai language, or English in Thailand): Thai dishes rank first among equal matches (O1). A
 * wrong guess only changes the order. */
/** Thai dishes first: the phone's languages include Thai, unless Settings says otherwise (M9a) */
export const thaiByLanguage = () => typeof navigator !== 'undefined' && (navigator.languages ?? [navigator.language]).some((l) => /^th\b|-TH\b/i.test(l));
export const thaiFirst = () => prefs.thai ?? thaiByLanguage();

/** Scored match over name and aliases: a whole match beats prefix beats word start beats substring, then Thai dishes when
 * `thai`, then shorter names. No library. */
export function searchFoods(foods: Food[], query: string, limit = 30, thai = false): Food[] {
  const raw = norm(query);
  if (!raw) return [];
  const fo = fold(query);
  const q = { raw, fold: fo, words: fo.split(' '), compact: compact(query) };
  const local = (f: Food) => (thai && f.tags.includes('thai') ? 1 : 0);
  return foods
    .map((f) => ({ f, s: score(f, q) }))
    .filter((x) => x.s > 0)
    .sort((a, b) => b.s - a.s || local(b.f) - local(a.f) || a.f.name.length - b.f.name.length || a.f.name.localeCompare(b.f.name))
    .slice(0, limit)
    .map((x) => x.f);
}

const r1 = (n: number) => Math.round(n * 10) / 10;
type Per100 = FoodMemory['per100'];
const at = (p: Per100, grams: number) => {
  const k = grams / 100;
  return { kcal: Math.round(p.kcal * k), protein: r1(p.protein * k), carbs: r1(p.carbs * k), fat: r1(p.fat * k) };
};
/** A meal item for this many grams of a food: whole kcal, macros to one decimal, labelled Database, or Yours when the
 * user's own values for the food are given (F15). */
export function itemFor(f: Food, grams: number, mine?: Per100): MealItem {
  return { name: f.name, grams, ...at(mine ?? f.per100, grams), source: mine ? 'yours' : 'db', foodId: f.id };
}

/** Where remembered nutrition is kept for an item: its table id, or its normalised name when it has none (a name in a
 * script `norm` drops, Chinese say, keeps its own lower case so two such names never share one memory). */
export const foodKey = (i: { foodId?: string | null; name: string }) => i.foodId || `name:${norm(i.name) || i.name.trim().toLowerCase()}`.slice(0, 80);
/** The item at its grams with the user's values per 100 g, labelled Yours. */
export const withMine = (i: MealItem, mine: Per100): MealItem => ({ ...i, ...at(mine, i.grams ?? 0), source: 'yours' });
/** An item's values per 100 g, to two decimals so the same grams give back the same numbers; null without grams. */
export function per100Of(i: MealItem): Per100 | null {
  if (!i.grams) return null;
  const k = 100 / i.grams;
  const r2 = (n: number) => Math.round(n * k * 100) / 100;
  return { kcal: r2(i.kcal), protein: r2(i.protein), carbs: r2(i.carbs), fat: r2(i.fat) };
}
